{
  "name": "analytics-pipeline",
  "version": "1.0.0",
  "description": "Real-time analytics pipeline",
  "main": "index.js",
  "scripts": {
    "start": "node index.js",
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "keywords": [],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "express": "^4.18.0",
    "kafkajs": "^2.2.0",
    "@clickhouse/client": "^0.2.0"
  }
}

const express = require('express');
const { Kafka } = require('kafkajs');
const { createClient } = require('@clickhouse/client');

const app = express();
const port = 3000;

// Initialize Kafka
const kafka = new Kafka({
  clientId: 'analytics-pipeline',
  brokers: ['localhost:9092'],
  retry: {
    initialRetryTime: 100,
    retries: 8
  }
});

const producer = kafka.producer({
  allowAutoTopicCreation: true,
  transactionTimeout: 30000
});

const consumer = kafka.consumer({
  groupId: 'analytics-consumer',
  sessionTimeout: 30000,
  heartbeatInterval: 3000
});

// Initialize ClickHouse
const clickhouse = createClient({
  url: 'http://localhost:8123',
  database: 'analytics'
});

app.use(express.json());

// Middleware for performance tracking
app.use((req, res, next) => {
  req.startTime = Date.now();
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Event ingestion endpoint
app.post('/events', async (req, res) => {
  try {
    const event = req.body;

    // Validate event structure
    if (!event.event_id || !event.event_ts || !event.user_id || !event.product_id || !event.event_type) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    // Send to Kafka for buffering
    await producer.send({
      topic: 'events',
      messages: [{
        key: event.event_id,
        value: JSON.stringify(event),
        timestamp: new Date().getTime()
      }]
    });

    const duration = Date.now() - req.startTime;
    res.json({ status: 'accepted', event_id: event.event_id, duration_ms: duration });
  } catch (error) {
    console.error('Ingestion error:', error);
    const duration = Date.now() - req.startTime;
    res.status(500).json({ error: 'Internal server error', duration_ms: duration });
  }
});

// Dashboard endpoint: Top products by conversion
app.get('/api/top-products', async (req, res) => {
  try {
    const query = `
      SELECT
        product_id,
        countIf(event_type = 'view') as views,
        countIf(event_type = 'cart') as cart_adds,
        countIf(event_type = 'purchase') as purchases,
        (purchases * 100.0 / views) as conversion_rate,
        sum(multiIf(event_type = 'purchase' AND JSONHas(properties, 'price'),
                   JSONExtractFloat(properties, 'price'), 0)) as revenue
      FROM events
      GROUP BY product_id
      ORDER BY purchases DESC, conversion_rate DESC
      LIMIT 10
    `;

    const result = await clickhouse.query({ query });
    const data = await result.json();

    const duration = Date.now() - req.startTime;
    res.json({
      data: data.data || [],
      duration_ms: duration,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Top products error:', error);
    const duration = Date.now() - req.startTime;
    res.status(500).json({ error: 'Query failed', duration_ms: duration });
  }
});

// Dashboard endpoint: Conversion funnel
app.get('/api/funnel', async (req, res) => {
  try {
    const query = `
      SELECT
        event_type,
        count() as count,
        uniq(user_id) as unique_users
      FROM events
      GROUP BY event_type
      ORDER BY
        CASE event_type
          WHEN 'view' THEN 1
          WHEN 'cart' THEN 2
          WHEN 'purchase' THEN 3
        END
    `;

    const result = await clickhouse.query({ query });
    const data = await result.json();

    // Calculate conversion rates
    const funnelData = data.data || [];
    let conversionFunnel = [];

    for (let i = 0; i < funnelData.length; i++) {
      const step = funnelData[i];
      const conversionRate = i > 0 ?
        (step.count * 100 / funnelData[0].count) : 100;

      conversionFunnel.push({
        step: step.event_type,
        count: step.count,
        unique_users: step.unique_users,
        conversion_rate: Math.round(conversionRate * 100) / 100
      });
    }

    const duration = Date.now() - req.startTime;
    res.json({
      funnel: conversionFunnel,
      duration_ms: duration,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Funnel error:', error);
    const duration = Date.now() - req.startTime;
    res.status(500).json({ error: 'Query failed', duration_ms: duration });
  }
});

// Dashboard endpoint: Hourly activity
app.get('/api/hourly-activity', async (req, res) => {
  try {
    const query = `
      SELECT
        toStartOfHour(event_ts) as hour,
        event_type,
        count() as count
      FROM events
      WHERE event_ts >= now() - INTERVAL 24 HOUR
      GROUP BY hour, event_type
      ORDER BY hour DESC, event_type
    `;

    const result = await clickhouse.query({ query });
    const data = await result.json();

    const duration = Date.now() - req.startTime;
    res.json({
      data: data.data || [],
      duration_ms: duration,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Hourly activity error:', error);
    const duration = Date.now() - req.startTime;
    res.status(500).json({ error: 'Query failed', duration_ms: duration });
  }
});

// Kafka consumer for processing events
async function startConsumer() {
  console.log('Starting Kafka consumer...');

  await consumer.connect();
  await consumer.subscribe({ topic: 'events', fromBeginning: true });

  await consumer.run({
    eachMessage: async ({ topic, partition, message }) => {
      try {
        const event = JSON.parse(message.value.toString());

        // Insert into ClickHouse
        await clickhouse.insert({
          table: 'events',
          values: [{
            event_id: event.event_id,
            event_ts: event.event_ts,
            user_id: event.user_id,
            product_id: event.product_id,
            event_type: event.event_type,
            properties: JSON.stringify(event.properties || {}),
            ingested_at: new Date().toISOString().replace('T', ' ').substring(0, 19)
          }],
          format: 'JSONEachRow'
        });

        console.log(`Processed event: ${event.event_id} (${event.event_type})`);
      } catch (error) {
        console.error('Consumer error:', error);
      }
    }
  });
}

// Initialize connections and start server
async function start() {
  try {
    console.log('Initializing analytics pipeline...');

    // Test ClickHouse connection
    await clickhouse.query({ query: 'SELECT 1' });
    console.log('✓ ClickHouse connected');

    // Connect Kafka producer
    await producer.connect();
    console.log('✓ Kafka producer connected');

    // Start Kafka consumer
    await startConsumer();
    console.log('✓ Kafka consumer started');

    // Start HTTP server
    app.listen(port, () => {
      console.log(`✓ Analytics API server listening on port ${port}`);
      console.log(`Ingestion endpoint: http://localhost:${port}/events`);
      console.log(`Dashboard endpoints:`);
      console.log(`  - Top products: http://localhost:${port}/api/top-products`);
      console.log(`  - Conversion funnel: http://localhost:${port}/api/funnel`);
      console.log(`  - Hourly activity: http://localhost:${port}/api/hourly-activity`);
    });

  } catch (error) {
    console.error('Startup error:', error);
    process.exit(1);
  }
}

// Graceful shutdown
process.on('SIGINT', async () => {
  console.log('\nShutting down gracefully...');
  await producer.disconnect();
  await consumer.disconnect();
  await clickhouse.close();
  process.exit(0);
});

start().catch(console.error);

const fs = require('fs');
const path = require('path');

async function loadEvents() {
  const eventsDir = '/data/events';
  const apiUrl = 'http://localhost:3000/events';

  try {
    const files = fs.readdirSync(eventsDir).filter(f => f.endsWith('.json'));
    console.log(`Loading ${files.length} events...`);

    let successCount = 0;
    let errorCount = 0;

    for (const file of files.sort()) {
      try {
        const filePath = path.join(eventsDir, file);
        const eventData = JSON.parse(fs.readFileSync(filePath, 'utf8'));

        const response = await fetch(apiUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(eventData)
        });

        if (response.ok) {
          const result = await response.json();
          console.log(`✓ ${file}: ${result.event_id} (${result.duration_ms}ms)`);
          successCount++;
        } else {
          const error = await response.text();
          console.error(`✗ ${file}: ${error}`);
          errorCount++;
        }

        // Small delay to avoid overwhelming the system
        await new Promise(resolve => setTimeout(resolve, 10));

      } catch (error) {
        console.error(`✗ Error processing ${file}:`, error.message);
        errorCount++;
      }
    }

    console.log(`\nLoad complete: ${successCount} success, ${errorCount} errors`);
    return successCount;

  } catch (error) {
    console.error('Failed to load events:', error);
    return 0;
  }
}

loadEvents().then(count => {
  console.log(`\nLoaded ${count} events into the pipeline`);
  process.exit(0);
}).catch(error => {
  console.error('Load failed:', error);
  process.exit(1);
});

