const fs = require('fs');
const path = require('path');
const { createClient } = require('@clickhouse/client');

// Initialize ClickHouse
const clickhouse = createClient({
  url: 'http://localhost:8123',
  database: 'analytics'
});

async function loadEventsDirectly() {
  const eventsDir = '/data/events';

  try {
    const files = fs.readdirSync(eventsDir).filter(f => f.endsWith('.json'));
    console.log(`Loading ${files.length} events directly into ClickHouse...`);

    const events = [];

    for (const file of files.sort()) {
      const filePath = path.join(eventsDir, file);
      const eventData = JSON.parse(fs.readFileSync(filePath, 'utf8'));

      events.push({
        event_id: eventData.event_id,
        event_ts: new Date(eventData.event_ts).toISOString().replace('T', ' ').substring(0, 19),
        user_id: eventData.user_id,
        product_id: eventData.product_id,
        event_type: eventData.event_type,
        properties: JSON.stringify(eventData.properties || {}),
        ingested_at: new Date().toISOString().replace('T', ' ').substring(0, 19)
      });
    }

    // Batch insert all events
    await clickhouse.insert({
      table: 'events',
      values: events,
      format: 'JSONEachRow'
    });

    console.log(`✓ Successfully loaded ${events.length} events into ClickHouse`);

    // Verify the count
