    const topProductsTime = Date.now() - testStart;

    const funnelStart = Date.now();
    const funnelResponse = await fetch('http://localhost:3000/api/funnel');
    const funnelData = await funnelResponse.json();
    const funnelTime = Date.now() - funnelStart;

    console.log(`\n⚡ PERFORMANCE:`);
